### 6.2 Pure DOM Node Replacements

#### 1. Play/Pause SVG Icon (`setPlayState`):
`test-m5.js:942` asserts: `assert(playBtn.innerHTML.includes('rect'))` and `assert(playBtn.innerHTML.includes('polygon'))`.
Replacing `.innerHTML =` with `createElementNS('http://www.w3.org/2000/svg', ...)` creates true SVG DOM nodes, which JSDOM and browsers serialize identically when reading `playBtn.innerHTML`. Thus, zero DOM sinks are used AND the assertion passes 100%!

```javascript
setPlayState: function (isPlaying) {
  if (!this._dom.playBtn) this._cacheDom();
  var d = this._dom;
  if (!d.playBtn) return;

  var svgNS = 'http://www.w3.org/2000/svg';

  if (isPlaying) {
    d.playBtn.title = 'Pause';
    d.playBtn.setAttribute('aria-label', 'Pause');
    if (d.playIcon) {
      while (d.playIcon.firstChild) {
        d.playIcon.removeChild(d.playIcon.firstChild);
      }
      var r1 = document.createElementNS(svgNS, 'rect');
      r1.setAttribute('x', '6');
      r1.setAttribute('y', '4');
      r1.setAttribute('width', '4');
      r1.setAttribute('height', '16');
      var r2 = document.createElementNS(svgNS, 'rect');
      r2.setAttribute('x', '14');
      r2.setAttribute('y', '4');
      r2.setAttribute('width', '4');
      r2.setAttribute('height', '16');
      d.playIcon.appendChild(r1);
      d.playIcon.appendChild(r2);
    }
    this.resetIdleTimer();
  } else {
    d.playBtn.title = 'Play';
    d.playBtn.setAttribute('aria-label', 'Play');
    if (d.playIcon) {
      while (d.playIcon.firstChild) {
        d.playIcon.removeChild(d.playIcon.firstChild);
      }
      var poly = document.createElementNS(svgNS, 'polygon');
      poly.setAttribute('points', '5 3 19 12 5 21 5 3');
      d.playIcon.appendChild(poly);
    }
    if (this._idleTimer) {
      clearTimeout(this._idleTimer);
      this._idleTimer = null;
    }
    this.showHUD();
  }
}
```

#### 2. Seeking Feedback Toast Icon (`showSeekFeedback`):
```javascript
showSeekFeedback: function (isForward, seconds) {
  if (!this._dom.feedbackToast) this._cacheDom();
  var d = this._dom;
  if (!d.feedbackToast) return;

  var sec = (typeof seconds === 'number' && !isNaN(seconds)) ? Math.abs(seconds) : 15;
  var text = isForward ? ('Forward +' + sec + 's') : ('Rewind -' + sec + 's');
  if (d.feedbackText) d.feedbackText.textContent = text;

  if (d.feedbackIcon) {
    var svgNS = 'http://www.w3.org/2000/svg';
    while (d.feedbackIcon.firstChild) {
      d.feedbackIcon.removeChild(d.feedbackIcon.firstChild);
    }
    var pl = document.createElementNS(svgNS, 'polyline');
    var pt = document.createElementNS(svgNS, 'path');
    if (isForward) {
      pl.setAttribute('points', '23 4 23 10 17 10');
      pt.setAttribute('d', 'M20.49 15a9 9 0 1 1-2.12-9.36L23 10');
    } else {
      pl.setAttribute('points', '1 4 1 10 7 10');
      pt.setAttribute('d', 'M3.51 15a9 9 0 1 0 2.13-9.36L1 10');
    }
    d.feedbackIcon.appendChild(pl);
    d.feedbackIcon.appendChild(pt);
  }

  d.feedbackToast.style.display = 'flex';
  if (this._toastTimer) clearTimeout(this._toastTimer);
  this._toastTimer = setTimeout(function () {
    if (d.feedbackToast) d.feedbackToast.style.display = 'none';
  }, 1200);
}
```

#### 3. Modal List Clearing & Item Construction (Explorer 2 Alignment):
- Clear lists using: `while (container.firstChild) container.removeChild(container.firstChild);`
- Build list items using `document.createElement('div')`, `document.createElement('span')`, `item.appendChild(...)`, and `element.textContent = ...`.

